fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Since tol is strictly positive, unwrap absolute difference and compare strictly less than tol.
    // Use i16 to prevent possible overflow when subtracting.
    let diff = (a as i16) - (b as i16);
    diff > -(tol as i16) && diff < (tol as i16)
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // Assumptions guaranteed: a.len() == b.len(), len > 0, tol > 0
    
    a.iter()
        .zip(b.iter())
        .map(|(&x, &y)| is_close_i8(x, y, tol))
        .collect()
}